/* DPB1 golden: reconstructed + in-loop-deblocked reference pictures.
 *
 * Golden provenance (byte-exact, no approximations): a fixed 32x32, two-frame
 * I420 clip (deterministic gradient, 3072 bytes) is encoded with the vendored
 * x264: --preset veryfast --qp 26 --bframes 0 --ref 1 --threads 1, slice
 * alpha/beta offsets 0.  x264's log: frame I QP 23/1125 bytes, frame P QP 26/
 * 488 bytes.  A *scratch copy* of x264 (never a repository file) was
 * instrumented at:
 *     encoder/encoder.c:fdec_filter_row() pass==0  -> pre-deblock fdec rows;
 *     encoder/encoder.c:2470 after x264_frame_expand_border() -> post-deblock
 *                                  fdec planes and h->mb state arrays.
 *   Frame 0 (I): the in-loop filter changes 70 luma / 25 chroma bytes.
 *   Frame 1 (P): the in-loop filter changes 102 luma / 50 chroma bytes.
 *   Phoenix's stored reference planes are byte-identical to x264's decoded
 *   picture in both cases, including the P frame's inter bs/ref/mv path.
 *
 * Authoritative x264 source lines:
 *   encoder/macroblock.c:1438-1622  x264_macroblock_deblock_strength();
 *   encoder/encoder.c:3057          fref is reconstructed, not source;
 *   encoder/encoder.c:2456-2470     deblock per MB row, then expand border;
 *   common/deblock.c:378-606        edge loop ported as
 *                                   phx_frame_deblock_ex();
 *   common/frame.c:535-553/633-638  luma / NV12 chroma border replication;
 *   common/frame.c:176-180          fdec->mv/ref arrays (state dump layout).
 *
 * SHADER: C — serial host test; the deblock work under test is SHADER B.
 *
 * Limitations reported to the orchestrator: progressive 4:2:0 NV12 only;
 * MBAFF and MMCO are not implemented (IDR reset + short-term overflow eviction
 * only).  Lowres planes of a stored reference are not regenerated; ME uses the
 * full-resolution plane/plane_chroma, as in phx_me16().
 */
