static int one_reflist_golden(const unsigned char *g, size_t len,
                              const unsigned char *blob, int code)
{
    size_t p = 0;
    int h[14];
    for (int i = 0; i < 14; i++) {
        memcpy(&h[i], blob + p, 4); p += 4;
    }
    (void)g;
    if (len != (size_t)(56 + 16*(h[4]+h[5]) + 20*h[12])) {
        printf("REFLIST f%d bad length %d\n", code, (int)len); return 1;
    }
    if (h[0] != code) { printf("REFLIST f%d wrong coding index %d\n",
                               code, h[0]); return 1; }

    int x_frame_num[2][PHX_DPB_REF_MAX], x_poc[2][PHX_DPB_REF_MAX];
    int x_frame[2][PHX_DPB_REF_MAX], x_type[2][PHX_DPB_REF_MAX];
    for (int list = 0; list < 2; list++)
        for (int i = 0; i < h[4+list]; i++) {
            int v[4]; memcpy(v, blob + p, 16); p += 16;
            x_frame_num[list][i] = v[0]; x_poc[list][i] = v[1];
            x_frame[list][i] = v[2]; x_type[list][i] = v[3];
        }
    phx_dpb_t dpb;
    memset(&dpb, 0, sizeof(dpb));
    dpb.n_pictures = h[12];
    if (dpb.n_pictures > PHX_DPB_MAX_PICTURES) return 1;
    for (int i = 0; i < dpb.n_pictures; i++) {
        int v[5]; memcpy(v, blob + p, 20); p += 20;
        dpb.pictures[i].i_frame_num = v[0];
        dpb.pictures[i].i_poc = v[1];
        dpb.pictures[i].i_frame = v[2];
        dpb.pictures[i].i_type = v[3];
        dpb.pictures[i].b_kept_as_ref = v[4];
        dpb.pictures[i].frame = NULL;       /* metadata-only fixture */
    }
    if (p != len) { printf("REFLIST f%d parse mismatch\n", code); return 1; }

    phx_dpb_list_cfg_t cfg;
    memset(&cfg, 0, sizeof(cfg));
    cfg.frame_reference = h[13];           /* encoder.c:2366 */
    phx_dpb_ref_lists_t out;
    int rc = phx_dpb_init_ref_lists(&dpb, &out, h[2], h[1], h[3], &cfg);
    int bad = 0;
    if (rc) { printf("REFLIST f%d init rc=%d\n", code, rc); return 1; }
    if (out.i_ref[0] != h[4] || out.i_ref[1] != h[5] ||
        out.b_ref_reorder[0] != h[6] || out.b_ref_reorder[1] != h[7]) bad++;
    /* encoder.c:2343 reads h->fref[list][0] even when i_ref[list]==0, so
     * x264 leaves a stale fref_nearest for an empty list.  Only the nearest
     * of a non-empty list is semantically defined and asserted here. */
    if (h[4] && ((out.fref_nearest[0] ? out.fref_nearest[0]->i_poc : -1) != h[8] ||
                 (out.fref_nearest[0] ? out.fref_nearest[0]->i_frame : -1) != h[9])) bad++;
    if (h[5] && ((out.fref_nearest[1] ? out.fref_nearest[1]->i_poc : -1) != h[10] ||
                 (out.fref_nearest[1] ? out.fref_nearest[1]->i_frame : -1) != h[11])) bad++;
    for (int list = 0; list < 2; list++)
        for (int i = 0; i < h[4+list]; i++)
            if (out.ref_frame_num[list][i] != x_frame_num[list][i] ||
                out.ref_poc[list][i] != x_poc[list][i] ||
                out.ref_frame[list][i] != x_frame[list][i] ||
                out.ref_type[list][i] != x_type[list][i]) bad++;
    printf("REFLIST f%d (%s display=%d POC=%d): L0=[", code,
           h[3] == 0 ? "P" : h[3] == 1 ? "B" : "I", h[1], h[2]);
    for (int i = 0; i < h[4]; i++)
        printf("%s(fn=%d,poc=%d,disp=%d)", i ? " " : "",
               x_frame_num[0][i], x_poc[0][i], x_frame[0][i]);
    printf("] L1=[");
    for (int i = 0; i < h[5]; i++)
        printf("%s(fn=%d,poc=%d,disp=%d)", i ? " " : "",
               x_frame_num[1][i], x_poc[1][i], x_frame[1][i]);
    printf("] reorder=%d/%d nearestPOC=%d/%d %s\n",
           h[6], h[7], h[8], h[10], bad ? "MISMATCH" : "byte-identical");
    return bad;
}

static int check_reflist_golden(void)
{
    int bad = 0;
    bad |= one_reflist_golden(reflist_f1, sizeof(reflist_f1), reflist_f1, 1);
    bad |= one_reflist_golden(reflist_f2, sizeof(reflist_f2), reflist_f2, 2);
    bad |= one_reflist_golden(reflist_f3, sizeof(reflist_f3), reflist_f3, 3);
    bad |= one_reflist_golden(reflist_f4, sizeof(reflist_f4), reflist_f4, 4);

    /* Accessor smoke: B1's L1[0] must be the future P at display 3. */
    phx_dpb_t dpb;
    memset(&dpb, 0, sizeof(dpb));
    dpb.n_pictures = 2;
    dpb.pictures[0].i_frame_num = 0; dpb.pictures[0].i_poc = 0;
    dpb.pictures[0].i_frame = 0; dpb.pictures[0].b_kept_as_ref = 1;
    dpb.pictures[1].i_frame_num = 1; dpb.pictures[1].i_poc = 6;
    dpb.pictures[1].i_frame = 3; dpb.pictures[1].b_kept_as_ref = 1;
    phx_dpb_ref_lists_t l;
    if (phx_dpb_init_ref_lists(&dpb, &l, 2, 1, PHX_SLICE_B, NULL) ||
        l.i_ref[0] != 1 || l.i_ref[1] != 1 ||
        phx_dpb_ref_frame_num(&l, 0, 0) != 0 ||
        phx_dpb_ref_poc(&l, 0, 0) != 0 ||
        phx_dpb_ref_frame_num(&l, 1, 0) != 1 ||
        phx_dpb_ref_poc(&l, 1, 0) != 6) {
        printf("REFLIST accessor smoke mismatch\n"); bad = 1;
    }
    /* The fixture carries no planes, so _at() accessors return NULL by design. */
    return bad;
}


