static int check_fdec64_golden(void)
{
    const unsigned char *g = fdec64_f0;
    size_t pos = 0;
    int mbw = rdi(g, &pos), mbh = rdi(g, &pos), fs = rdi(g, &pos);
    (void)rdi(g, &pos);                              /* x264 chroma stride */
    int w = rdi(g, &pos), h = rdi(g, &pos);
    int alpha = rdi(g, &pos), beta = rdi(g, &pos), coff = rdi(g, &pos);
    int bcabac = rdi(g, &pos);
    int mbn = mbw*mbh;
    size_t npre = (size_t)mbn*16*fs;
    const uint8_t *pre_fdec = tk(g, &pos, npre);
    const uint8_t *pre_uv = tk(g, &pos, (size_t)w*h/2);
    const uint8_t *post_y = tk(g, &pos, (size_t)w*h);
    const uint8_t *post_uv = tk(g, &pos, (size_t)w*h/2);
    const uint8_t *type = tk(g, &pos, mbn);
    const uint8_t *nnz = tk(g, &pos, (size_t)mbn*48);
    const uint8_t *cbpb = tk(g, &pos, (size_t)mbn*2);
    const uint8_t *xf = tk(g, &pos, mbn);
    const uint8_t *ref0 = tk(g, &pos, (size_t)mbn*4);
    const uint8_t *ref1 = tk(g, &pos, (size_t)mbn*4);
    const uint8_t *mv0 = tk(g, &pos, (size_t)mbn*16*4);
    const uint8_t *mv1 = tk(g, &pos, (size_t)mbn*16*4);
    const uint8_t *qp8 = tk(g, &pos, mbn);
    tk(g, &pos, mbn);                                /* partition */
    const uint8_t *slt = tk(g, &pos, (size_t)mbn*4);
    const uint8_t *fld = tk(g, &pos, mbn);
    if (fs != 32 || mbn != 16 || pos != sizeof(fdec64_f0) ||
        alpha || beta || coff) {
        printf("FDEC64 bad header/length\n"); return 1;
    }

    phx_mb_state_t *s = phx_mb_state_new(mbw, mbh);
    int *qp = (int *)malloc((size_t)mbn*sizeof(int));
    uint8_t *src = (uint8_t *)malloc(npre);
    uint8_t *src_copy = (uint8_t *)malloc(npre);
    phx_dpb_t *d = phx_dpb_create(w, h, 0);
    if (!s || !qp || !src || !src_copy || !d) { printf("FDEC64 OOM\n"); return 1; }
    for (int i = 0; i < mbn; i++) {
        s->type[i] = type[i];
        memcpy(s->non_zero_count[i], nnz + (size_t)i*48, 48);
        memcpy(&s->cbp[i], cbpb + (size_t)i*2, 2);
        s->mb_transform_size[i] = xf[i];
        memcpy(s->ref[0] + i*4, ref0 + i*4, 4);
        memcpy(s->ref[1] + i*4, ref1 + i*4, 4);
        memcpy(s->mv[0] + i*16, mv0 + (size_t)i*16*4, 64);
        memcpy(s->mv[1] + i*16, mv1 + (size_t)i*16*4, 64);
        int32_t v; memcpy(&v, slt + i*4, 4);
        s->slice_table[i] = (uint8_t)v;
        s->field[i] = fld[i];
        qp[i] = qp8[i];
    }
    s->slice_type = 2; s->b_cabac = bcabac;
    s->b_transform_8x8_mode = 1; s->b_interlaced = 0;
    memcpy(src, pre_fdec, npre); memcpy(src_copy, pre_fdec, npre);

    phx_dpb_store_params_t sp;
    memset(&sp, 0, sizeof(sp));
    sp.fdec_y = src; sp.fdec_y_stride = fs; sp.fdec_y_mb_major = 1;
    sp.fdec_uv = pre_uv; sp.fdec_uv_stride = w;
    sp.mb_state = s; sp.qp_array = qp; sp.qp = 26;
    sp.b_cabac = bcabac;
    sp.frame_num = 0; sp.poc = 0; sp.display_frame = 0;
    sp.i_type = 2; sp.b_kept_as_ref = 1;
    int rc = phx_dpb_store_frame(d, &sp);
    const phx_frame_t *r = phx_dpb_get_ref(d, 0);
    int bad = 0;
    if (rc || !r) { printf("FDEC64 store failed rc=%d\n", rc); bad = 1; }
    else {
        int dy=0, dc=0;
        for (int i = 0; i < w*h; i++)
            if (r->plane[i/w*r->i_stride + i%w] != post_y[i]) dy++;
        for (int i = 0; i < w*h/2; i++)
            if (r->plane_chroma[i/w*r->i_stride_planes[1] + i%w] != post_uv[i]) dc++;
        printf("FDEC64 64x64/16 MB per-MB stride=32: x264 full-plane diff "
               "luma=%d/%d chroma=%d/%d; raw=%d,%d,%d,%d post=%d,%d,%d,%d "
               "phx=%d,%d,%d,%d\n", dy, w*h, dc, w*h/2,
               pre_fdec[0],pre_fdec[1],pre_fdec[2],pre_fdec[3],
               post_y[0],post_y[1],post_y[2],post_y[3],
               r->plane[0],r->plane[1],r->plane[2],r->plane[3]);
        bad |= dy | dc;
    }
    if (memcmp(src, src_copy, npre)) {
        printf("FDEC64 source buffer was modified\n"); bad = 1;
    }
    phx_dpb_free(d); free(src); free(src_copy); free(qp);
    phx_mb_state_delete(s);
    return bad;
}


