static int check_ramp_golden(void)
{
    const unsigned char *g = ramp_f0;
    size_t pos = 0;
    int mbw = rdi(g,&pos), mbh = rdi(g,&pos), sy = rdi(g,&pos);
    (void)sy;
    int su = rdi(g,&pos), w = rdi(g,&pos), h = rdi(g,&pos);
    int alpha = rdi(g,&pos), beta = rdi(g,&pos), coff = rdi(g,&pos);
    int cabac = rdi(g,&pos), stype = rdi(g,&pos), fn0 = rdi(g,&pos);
    (void)su; (void)stype;
    const uint8_t *pre_y = tk(g,&pos,(size_t)w*h);
    const uint8_t *post_y = tk(g,&pos,(size_t)w*h);
    const uint8_t *border = tk(g,&pos,(size_t)(h+64)*(w+64));
    const uint8_t *type = tk(g,&pos,mbw*mbh);
    const uint8_t *nnz = tk(g,&pos,(size_t)mbw*mbh*48);
    const uint8_t *cbpb = tk(g,&pos,(size_t)mbw*mbh*2);
    const uint8_t *xf = tk(g,&pos,mbw*mbh);
    const uint8_t *ref0 = tk(g,&pos,(size_t)mbw*mbh*4);
    const uint8_t *ref1 = tk(g,&pos,(size_t)mbw*mbh*4);
    const uint8_t *mv0 = tk(g,&pos,(size_t)mbw*mbh*16*4);
    const uint8_t *mv1 = tk(g,&pos,(size_t)mbw*mbh*16*4);
    const uint8_t *qp8 = tk(g,&pos,mbw*mbh);
    tk(g,&pos,mbw*mbh);                              /* partition */
    const uint8_t *slt = tk(g,&pos,(size_t)mbw*mbh*4);
    const uint8_t *fld = tk(g,&pos,mbw*mbh);
    /* x264 medium/subme7 sets pps.i_chroma_qp_index_offset = -2 (base.c). */
    if (alpha || beta || (coff != 0 && coff != -2) ||
        pos != sizeof(ramp_f0) ||
        w != 64 || h != 64 || mbw != 4 || mbh != 4) {
        printf("RAMP bad header/length\n"); return 1;
    }
    int n = mbw*mbh, *qp = (int*)malloc((size_t)n*sizeof(int));
    phx_mb_state_t *s = phx_mb_state_new(mbw,mbh);
    uint8_t *mbuf = (uint8_t*)malloc((size_t)n*16*32);
    uint8_t *copy = (uint8_t*)malloc((size_t)n*16*32);
    uint8_t *dummy_uv = (uint8_t*)calloc((size_t)w*h/2, 1);
    phx_dpb_t *d = phx_dpb_create(w,h,0);
    if (!s || !qp || !mbuf || !copy || !dummy_uv || !d) {
        printf("RAMP OOM\n"); return 1;
    }
    for (int i = 0; i < n; i++) {
        s->type[i] = type[i];
        memcpy(s->non_zero_count[i], nnz + (size_t)i*48, 48);
        memcpy(&s->cbp[i], cbpb + i*2, 2);
        s->mb_transform_size[i] = xf[i];
        memcpy(s->ref[0] + i*4, ref0 + i*4, 4);
        memcpy(s->ref[1] + i*4, ref1 + i*4, 4);
        memcpy(s->mv[0] + i*16, mv0 + (size_t)i*16*4, 64);
        memcpy(s->mv[1] + i*16, mv1 + (size_t)i*16*4, 64);
        int32_t v; memcpy(&v, slt + i*4, 4);
        s->slice_table[i] = (uint8_t)v;
        s->field[i] = fld[i];
        qp[i] = qp8[i];
    }
    s->slice_type = stype; s->b_cabac = cabac;
    s->b_transform_8x8_mode = 1; s->b_interlaced = 0;
    /* MB-major 16x32 scratch, assembled by phx_dpb_store_frame(). */
    for (int my=0;my<mbh;my++) for (int mx=0;mx<mbw;mx++)
        for (int y=0;y<16;y++)
            memcpy(mbuf+((my*mbw+mx)*16+y)*32, pre_y+(my*16+y)*w+mx*16, 16);
    memcpy(copy, mbuf, (size_t)n*16*32);

    int bad = 0;
    for (int pass = 0; pass < 2; pass++) {
        phx_dpb_store_params_t p;
        memset(&p,0,sizeof(p));
        p.fdec_y = mbuf; p.fdec_y_stride = 32; p.fdec_y_mb_major = 1;
        p.fdec_uv = dummy_uv; p.fdec_uv_stride = w;
        p.mb_state = s; p.qp_array = qp; p.qp = 28; p.b_cabac = cabac;
        phx_deblock_cfg_t cfg; memset(&cfg,0,sizeof(cfg));
        cfg.chroma_qp_index_offset = coff;             /* x264 medium: -2 */
        if (pass == 0) cfg.disable_deblocking_filter_idc = 1; /* assembly only */
        p.cfg = &cfg;
        p.frame_num = fn0; p.poc = 0; p.display_frame = 0;
        p.i_type = stype; p.b_kept_as_ref = 1;
        if (phx_dpb_store_frame(d,&p)) { printf("RAMP store failed\n"); bad=1; break; }
        const phx_frame_t *r = phx_dpb_get_ref(d,fn0);
        if (!r) { printf("RAMP no ref\n"); bad=1; break; }
        const uint8_t *target = pass ? post_y : pre_y;
        int ad=0, af=-1;
        for (int y=0;y<h;y++) for (int x=0;x<w;x++) {
            int i=y*w+x;
            if (r->plane[y*r->i_stride+x] != target[i]) {
                ad++; if (af<0) af=i;
            }
        }
        printf("RAMP %s: full 16x16 active diff=%d/%d first=%d\n",
               pass ? "DEBLOCK" : "ASSEMBLY", ad, w*h, af);
        bad |= ad;
        if (pass) {
            int bd=0, act=0, pad=0;
            for (int y=-32;y<h+32;y++) for (int x=-32;x<w+32;x++) {
                int bi=(y+32)*(w+64)+(x+32);
                if (r->plane[y*r->i_stride+x] != border[bi]) {
                    bd++;
                    if (y>=0&&y<h&&x>=0&&x<w) act++; else pad++;
                }
            }
            printf("RAMP NEIGHBOURHOOD y=-32..%d x=-32..%d: diff=%d "
                   "(active=%d pad=%d)\n", h+31, w+31, bd, act, pad);
            bad |= bd;
            int coords[][2] = {{4,13},{8,14},{16,-2},{16,-1},{0,-1},{64,-2},{64,-1}};
            for (unsigned k=0;k<sizeof(coords)/sizeof(coords[0]);k++) {
                int y=coords[k][0], x=coords[k][1], bi=(y+32)*(w+64)+(x+32);
                printf("  y=%3d x=%3d x264=%3d phx=%3d\n", y,x,
                       border[bi], r->plane[y*r->i_stride+x]);
            }
        }
        phx_dpb_reset(d);
    }
    if (memcmp(mbuf,copy,(size_t)n*16*32)) {
        printf("RAMP source buffer modified\n"); bad=1;
    }
    phx_dpb_free(d); free(mbuf); free(copy); free(dummy_uv); free(qp);
    phx_mb_state_delete(s);
    return bad;
}

int main(void)
{
    int bad = check_golden(golden_f0, sizeof(golden_f0), 0, 2, "GOLDEN I") |
              check_golden(golden_f1, sizeof(golden_f1), 1, 0, "GOLDEN P") |
              check_reflist_golden() | check_col_golden() | check_fdec64_golden() | check_ramp_golden() | check_api();
    printf("phx_dpb: %s\n", bad ? "FAIL" : "PASS");
    return bad;
}
